-- 1. Strict Quorum: W + R > N (Guarantees overlap, linearizable with serial)
CONSISTENCY QUORUM;
SELECT balance FROM user_accounts WHERE user_id = 'usr_102';

-- 2. Low-Latency Local Read (May return stale data during replication lag)
CONSISTENCY ONE;
SELECT * FROM user_feed WHERE user_id = 'usr_102' LIMIT 20;
